def verify_pinned_pier(root: Path | None = None) -> None:
    root = root or Path(inspect.getfile(DockerEnvironment)).resolve().parents[2]
    for name, expected in PINNED_HASHES.items():
        path = root / name
        require(path.is_file() and hashlib.sha256(path.read_bytes()).hexdigest() == expected, "incompatible pinned Pier source")
